using System.Security.Claims;namespace Dhole.Content.Api.Extensions;public static class HttpContextAuditExtensions{public static Guid? GetCurrentUserId(this HttpContext context){var raw=context.User.FindFirstValue(ClaimTypes.NameIdentifier)??context.User.FindFirstValue("sub")??context.User.FindFirstValue("user_id");return Guid.TryParse(raw,out var id)?id:null;}public static string? GetCurrentUserName(this HttpContext context)=>context.User.FindFirstValue(ClaimTypes.Name)??context.User.FindFirstValue("name")??context.User.Identity?.Name;}
